import Header from '../components/Header';
import Footer from '../components/Footer';
import { useState, useContext } from 'react';
import { PreferencesContext } from '../context/indexContext';
import '../styles/Preferences.css';

const themes = [
    { id: "ocean", label: "Mode Zikéolarge #SouslOcean" },
    { id: "maya", label: "Mode zzzzzzzzzzzzzzzzzzzzzzzzikeo #MayalAbeille" },
    { id: "eolienne", label: "Mode Zikéolienne #EnRotationDansLeVent" },
    { id: "oblique", label: "Mode Zikéoblique #PencheDansLeSpectre" },
    { id: "nuit", label: "Mode Zikéolit #SousLaLune" },
    { id: "automne", label: "Mode Zikéotomne #FeuillesMortesEtMusique" }
];

function Preferences() {
    const { mode, setMode } = useContext(PreferencesContext);

    function CheckboxChange(e) {
        setMode(e.target.checked);
    }

    return (
        <div className={`preferences-page ${mode}-mode`}>
            <Header />

            <h1>Préférences</h1>

            {themes.map((theme) => (
                <label key={theme}>
                    <input
                        type="radio"
                        name="theme"
                        checked={mode === theme.id}
                        onChange={() => setMode(theme.id)}
                    />
                    {theme.label}
                </label>
            ))}

            <Footer />

        </div >
    )
}

export default Preferences;
